-- ADDON-31: Turnkey Projects — 25 complete businesses (4 live with packages, 21 register-interest), 12 Chinese factory hubs,
-- quote / interest leads with region round-robin routing, atlas signals.
-- Catalogue content (projects, hubs, packages, equipment) is the owner's product line, NOT demo data → is_seed = false.
-- Budgets are the rough planning figures from the design canvas (see ADDON-31 "What to decide").

-- ───────── settings / permissions ─────────
on conflict (key) do nothing;

on conflict do nothing;

-- sourcing staff region tag (lead routing)
alter table profiles add column if not exists region text;
do $$ begin
  alter table profiles add constraint profiles_region_check check (region is null or region in ('MENA','Africa','Europe','Indian subcontinent','SEA','Americas'));
exception when duplicate_object then null; end $$;

-- deterministic ids for catalogue rows (re-runnable seed)
create or replace function turnkey_uuid(p_slug text, p_tier int, p_line int default 0) returns uuid
language sql immutable as $$ select md5('turnkey:' || p_slug || ':' || p_tier || ':' || p_line)::uuid $$;

-- ───────── tables ─────────
create table if not exists turnkey_hubs (
  hub_id text primary key,
  name text not null,
  province text,
  country text not null default 'CN',
  lat numeric, lng numeric,
  known_for text,
  sort_rank int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists turnkey_projects (
  project_id text primary key check (project_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null,
  category text not null check (category in ('self-service','food','leisure','small-factory','infrastructure','fit-out')),
  short_reason text,
  starting_budget_usd int check (starting_budget_usd is null or starting_budget_usd >= 0),
  budget_unit text,                         -- 'court' | 'room' → "From $22 k/court"
  lead_time_days int check (lead_time_days is null or lead_time_days > 0),
  best_markets text[] not null default '{}',
  factory_hub_ids text[] not null default '{}',
  hub_label text,
  status text not null default 'register-interest' check (status in ('register-interest','live','archived')),
  is_starter_pick boolean not null default false,
  starter_rank int check (starter_rank between 1 and 5),
  sort_rank int not null default 0,
  hero_image_path text,
  overview_md text,
  highlights text[] not null default '{}',  -- hero ticks
  earn jsonb not null default '[]',         -- 3 cards under "What this tier typically earns" (label/value/note)
  four_tests jsonb not null default '{}',
  seo_title text, seo_description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  is_seed boolean not null default false,
  constraint turnkey_starter_rank_needs_pick check ((is_starter_pick and starter_rank is not null) or (not is_starter_pick and starter_rank is null)),
  constraint turnkey_four_tests_shape check (jsonb_typeof(four_tests) = 'object')
);
create unique index if not exists turnkey_projects_starter_rank_key on turnkey_projects(starter_rank) where is_starter_pick and status <> 'archived';

create table if not exists turnkey_packages (
  package_id uuid primary key default gen_random_uuid(),
  project_id text not null references turnkey_projects(project_id) on delete cascade,
  tier_name text not null,
  tier_rank int not null check (tier_rank between 1 and 9),
  tier_label text,
  starting_budget_usd int,
  starting_budget_notes text,
  capacity_label text,
  items_count int,
  space_label text,
  container_label text,
  lead_time_days int,
  monthly_revenue_low int, monthly_revenue_high int,
  payback_months_low int, payback_months_high int,
  summary_md text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, tier_rank)
);

create table if not exists turnkey_equipment (
  line_id uuid primary key default gen_random_uuid(),
  package_id uuid not null references turnkey_packages(package_id) on delete cascade,
  sort_order int not null default 0,
  group_label text,                          -- short tag shown in the thumb ("Cardio", "Str.")
  name text not null,
  quantity int not null default 1 check (quantity > 0),
  unit text,                                 -- 'set' etc.; null = "× quantity"
  spec_md text,
  supplier_hint text,
  supplier_id uuid references suppliers(id) on delete set null,
  budget_usd int,
  notes text
);
create index if not exists turnkey_equipment_package_idx on turnkey_equipment(package_id, sort_order);

create table if not exists turnkey_project_sources (   -- "Where it's sourced from" cards
  project_id text not null references turnkey_projects(project_id) on delete cascade,
  sort_order int not null default 0,
  region_label text not null,
  title text not null,
  description text,
  primary key (project_id, sort_order)
);

create sequence if not exists seq_turnkey_lead start 1;
create table if not exists turnkey_leads (
  lead_id uuid primary key default gen_random_uuid(),
  reference text not null unique default ('TK-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('seq_turnkey_lead')::text, 5, '0')),
  kind text not null check (kind in ('quote','interest')),
  project_id text not null references turnkey_projects(project_id),
  package_id uuid references turnkey_packages(package_id) on delete set null,
  buyer_user_id uuid references auth.users(id) on delete set null,
  org_id uuid references organizations(id) on delete set null,
  company_name text not null,
  contact_name text not null,
  email text not null check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  phone text,
  country text not null check (country ~ '^[A-Z]{2}$'),
  region text,
  preferred_delivery_term text check (preferred_delivery_term is null or preferred_delivery_term in ('FOB','CIF','DAP')),
  delivery_place text,                       -- port (CIF) or city (DAP)
  target_open_date date,
  floor_plan_storage_path text,
  message text check (message is null or length(message) <= 4000),
  status text not null default 'new' check (status in ('new','contacted','quoted','won','lost')),
  assigned_to uuid references auth.users(id) on delete set null,
  assigned_at timestamptz,
  rfq_id uuid references rfqs(id) on delete set null,
  source text not null default 'web',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  is_seed boolean not null default false
);
create index if not exists turnkey_leads_status_idx on turnkey_leads(status, created_at desc);
create index if not exists turnkey_leads_assigned_idx on turnkey_leads(assigned_to, created_at desc);
create index if not exists turnkey_leads_buyer_idx on turnkey_leads(buyer_user_id);

create table if not exists turnkey_atlas_signals (
  id uuid primary key default gen_random_uuid(),
  project_id text references turnkey_projects(project_id) on delete cascade,
  hub_id text references turnkey_hubs(hub_id) on delete cascade,
  event text not null check (event in ('view','filter','tap_hub','interest')),
  country_from text,
  ts timestamptz not null default now(),
  constraint turnkey_signal_target check (project_id is not null or hub_id is not null)
);
create index if not exists turnkey_atlas_signals_idx on turnkey_atlas_signals(project_id, event, ts desc);

-- ───────── RLS ─────────
alter table turnkey_hubs enable row level security;
alter table turnkey_projects enable row level security;
alter table turnkey_packages enable row level security;
alter table turnkey_equipment enable row level security;
alter table turnkey_project_sources enable row level security;
alter table turnkey_leads enable row level security;
alter table turnkey_atlas_signals enable row level security;

drop policy if exists turnkey_hubs_read on turnkey_hubs;
create policy turnkey_hubs_read on turnkey_hubs for select using (true);
drop policy if exists turnkey_hubs_write on turnkey_hubs;
create policy turnkey_hubs_write on turnkey_hubs for all using (can('turnkey','edit')) with check (can('turnkey','edit'));

drop policy if exists turnkey_projects_read on turnkey_projects;
create policy turnkey_projects_read on turnkey_projects for select using (status <> 'archived' or can('turnkey','view'));
drop policy if exists turnkey_projects_write on turnkey_projects;
create policy turnkey_projects_write on turnkey_projects for all using (can('turnkey','edit')) with check (can('turnkey','edit'));

drop policy if exists turnkey_packages_read on turnkey_packages;
create policy turnkey_packages_read on turnkey_packages for select using (
  (is_active and exists (select 1 from turnkey_projects p where p.project_id = turnkey_packages.project_id and p.status <> 'archived')) or can('turnkey','view'));
drop policy if exists turnkey_packages_write on turnkey_packages;
create policy turnkey_packages_write on turnkey_packages for all using (can('turnkey','edit')) with check (can('turnkey','edit'));

drop policy if exists turnkey_equipment_read on turnkey_equipment;
create policy turnkey_equipment_read on turnkey_equipment for select using (
  exists (select 1 from turnkey_packages k join turnkey_projects p on p.project_id = k.project_id
          where k.package_id = turnkey_equipment.package_id and k.is_active and p.status <> 'archived') or can('turnkey','view'));
drop policy if exists turnkey_equipment_write on turnkey_equipment;
create policy turnkey_equipment_write on turnkey_equipment for all using (can('turnkey','edit')) with check (can('turnkey','edit'));

drop policy if exists turnkey_sources_read on turnkey_project_sources;
create policy turnkey_sources_read on turnkey_project_sources for select using (true);
drop policy if exists turnkey_sources_write on turnkey_project_sources;
create policy turnkey_sources_write on turnkey_project_sources for all using (can('turnkey','edit')) with check (can('turnkey','edit'));

-- leads: written only through submit_turnkey_lead (service role, rate-limited in the app); staff with turnkey:view read;
-- a signed-in buyer reads their own requests ("My turnkey projects").
drop policy if exists turnkey_leads_staff on turnkey_leads;
create policy turnkey_leads_staff on turnkey_leads for select using (can('turnkey','view') or can('requests','view'));
drop policy if exists turnkey_leads_own on turnkey_leads;
create policy turnkey_leads_own on turnkey_leads for select using (buyer_user_id = auth.uid());
drop policy if exists turnkey_leads_edit on turnkey_leads;
create policy turnkey_leads_edit on turnkey_leads for update using (can('turnkey','edit')) with check (can('turnkey','edit'));

drop policy if exists turnkey_signals_staff on turnkey_atlas_signals;
create policy turnkey_signals_staff on turnkey_atlas_signals for select using (can('turnkey','view'));
revoke insert, update, delete on turnkey_leads, turnkey_atlas_signals from anon, authenticated;
grant update (status, assigned_to, assigned_at, rfq_id, updated_at) on turnkey_leads to authenticated;

-- ───────── routing ─────────
create or replace function turnkey_region_for(p_country text) returns text
language sql immutable as $$
  select case
    when upper(p_country) = any (array['AE','SA','QA','KW','BH','OM','YE','IQ','IR','JO','LB','SY','PS','IL','TR','EG','LY','TN','DZ','MA']) then 'MENA'
    when upper(p_country) = any (array['NG','GH','KE','TZ','UG','ET','RW','ZA','ZM','ZW','MZ','AO','CM','CI','SN','ML','BF','NE','TD','SD','SS','SO','DJ','ER','MW','BW','NA','LS','SZ','MG','MU','SC','CD','CG','GA','GQ','BJ','TG','LR','SL','GN','GW','GM','CV','MR','BI','CF','ST','KM']) then 'Africa'
    when upper(p_country) = any (array['IN','PK','BD','LK','NP','BT','MV','AF']) then 'Indian subcontinent'
    when upper(p_country) = any (array['TH','VN','MY','SG','ID','PH','KH','LA','MM','BN','TL']) then 'SEA'
    when upper(p_country) = any (array['US','CA','MX','BR','AR','CL','CO','PE','EC','VE','UY','PY','BO','CR','PA','GT','HN','SV','NI','DO','CU','JM','TT','BS','BB','HT','PR']) then 'Americas'
    when upper(p_country) = any (array['GB','IE','FR','DE','NL','BE','LU','ES','PT','IT','CH','AT','DK','SE','NO','FI','IS','PL','CZ','SK','HU','RO','BG','GR','HR','SI','RS','BA','ME','MK','AL','EE','LV','LT','UA','MD','BY','CY','MT','RU']) then 'Europe'
    else null end
$$;

-- next sourcing agent for a region: active (not out of office), least recently assigned a turnkey lead
create or replace function turnkey_pick_assignee(p_region text) returns uuid
language sql stable security definer set search_path = public as $$
  select ur.user_id
  from user_roles ur join profiles pr on pr.id = ur.user_id
  where ur.role_code = 'sourcing_agent' and p_region is not null and pr.region = p_region and not coalesce(pr.out_of_office, false)
  order by (select max(l.assigned_at) from turnkey_leads l where l.assigned_to = ur.user_id) asc nulls first, ur.user_id
  limit 1
$$;

-- one entry point for both forms; called by the app with the service role after validation + rate limiting
create or replace function submit_turnkey_lead(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_proj turnkey_projects; v_pkg turnkey_packages; v_lead turnkey_leads; v_kind text := p->>'kind';
  v_region text; v_assignee uuid; v_title text;
begin
  select * into v_proj from turnkey_projects where project_id = p->>'project_id' and status <> 'archived';
  if not found then raise exception 'TURNKEY_PROJECT_NOT_FOUND'; end if;
  if v_kind = 'quote' and v_proj.status <> 'live' then raise exception 'TURNKEY_NOT_LIVE: % is open for register-interest only', v_proj.title; end if;
  if v_kind not in ('quote','interest') then raise exception 'TURNKEY_BAD_KIND'; end if;
  if nullif(p->>'package_id','') is not null then
    select * into v_pkg from turnkey_packages where package_id = (p->>'package_id')::uuid and project_id = v_proj.project_id;
    if not found then raise exception 'TURNKEY_PACKAGE_NOT_FOUND'; end if;
  end if;
  v_region := turnkey_region_for(p->>'country');
  v_assignee := turnkey_pick_assignee(v_region);
    preferred_delivery_term, delivery_place, target_open_date, floor_plan_storage_path, message, assigned_to, assigned_at, source)
  values (v_kind, v_proj.project_id, v_pkg.package_id, nullif(p->>'buyer_user_id','')::uuid, nullif(p->>'org_id','')::uuid,
    trim(p->>'company_name'), trim(p->>'contact_name'), lower(trim(p->>'email')), nullif(trim(p->>'phone'),''), upper(p->>'country'), v_region,
    nullif(p->>'delivery_term',''), nullif(trim(p->>'delivery_place'),''), nullif(p->>'target_open_date','')::date,
    nullif(p->>'floor_plan_path',''), nullif(trim(p->>'message'),''), v_assignee, case when v_assignee is not null then now() end, coalesce(p->>'source','web'))
  returning * into v_lead;
  if v_kind = 'interest' then
  end if;
  v_title := case v_kind when 'quote' then 'New turnkey quote request' else 'New turnkey interest' end;
  if v_assignee is not null then
    values (v_assignee, v_title, v_lead.reference || ' · ' || v_proj.title || coalesce(' · ' || v_pkg.tier_name, '') || ' · ' || v_lead.company_name || ' (' || v_lead.country || ')', '/admin/turnkey?lead=' || v_lead.lead_id);
  else -- triage pool: every admin + turnkey editor is told
    select distinct ur.user_id, v_title || ' — unassigned', v_lead.reference || ' · ' || v_proj.title || ' · ' || v_lead.company_name || ' (' || v_lead.country || '). No sourcing agent for ' || coalesce(v_region, 'this region') || ' — please assign.', '/admin/turnkey?lead=' || v_lead.lead_id
    from user_roles ur where ur.role_code = 'admin';
  end if;
  values (nullif(p->>'buyer_user_id','')::uuid, 'turnkey.lead_created', 'turnkey_leads', v_lead.lead_id::text,
          jsonb_build_object('reference', v_lead.reference, 'kind', v_kind, 'project', v_proj.project_id, 'assigned_to', v_assignee, 'region', v_region));
  return jsonb_build_object('lead_id', v_lead.lead_id, 'reference', v_lead.reference, 'assigned_to', v_assignee, 'region', v_region);
end $$;
revoke execute on function submit_turnkey_lead(jsonb) from public, anon, authenticated;
grant execute on function submit_turnkey_lead(jsonb) to service_role;

create or replace function log_turnkey_signal(p_event text, p_project text, p_hub text, p_country text) returns void
language sql security definer set search_path = public as $$
  select nullif(p_project,''), nullif(p_hub,''), p_event, nullif(upper(p_country),'')
  where p_event in ('view','filter','tap_hub') and (nullif(p_project,'') is not null or nullif(p_hub,'') is not null)
$$;
revoke execute on function log_turnkey_signal(text, text, text, text) from public, anon, authenticated;
grant execute on function log_turnkey_signal(text, text, text, text) to service_role;

